import{_ as a,o as i,c as e,ag as l}from"./chunks/framework.IxO3mcwW.js";const r="/getbiji-docs/images/internal-01.png",o="/getbiji-docs/images/internal-02.png",s="/getbiji-docs/images/internal-03.png",d="/getbiji-docs/images/internal-04.png",n="/getbiji-docs/images/internal-05.png",p="/getbiji-docs/images/internal-06.png",P=JSON.parse('{"title":"手机内录","description":"","frontmatter":{},"headers":[],"relativePath":"voice/internal.md","filePath":"voice/internal.md","lastUpdated":1773147350000}'),c={name:"voice/internal.md"};function h(u,t,g,m,b,_){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="手机内录" tabindex="-1">手机内录 <a class="header-anchor" href="#手机内录" aria-label="Permalink to &quot;手机内录&quot;">​</a></h1><blockquote><p>手机内录，边听边记，一气呵成！</p></blockquote><p>自动捕获手机播放的声音，AI同步转写文字，让你在听的同时就把重点内容记下来。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>线上学习</strong>：线上直播课程、讲座内容轻松记录</li><li><strong>视频记录</strong>：生成视频逐字稿 + 要点总结</li><li><strong>播客整理</strong>：语音+文字双轨保存，随时回顾不遗漏</li><li><strong>区分说话人</strong>：多个说话人，可以自动区分每个说话人内容</li></ul><h2 id="不适用的场景" tabindex="-1">不适用的场景 <a class="header-anchor" href="#不适用的场景" aria-label="Permalink to &quot;不适用的场景&quot;">​</a></h2><ul><li>录制拨打电话、语音通话、微信 QQ 通话</li><li>腾讯/飞书/钉钉会议等场景</li><li>带耳机等外部播放设备时也无法正常录制</li></ul><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><ol><li><p>打开 APP，点击首页底部「录音」按钮，选择「手机内录」</p></li><li><p>同意 Get 笔记使用手机录屏权限，然后点击红色按钮&quot;开始录制&quot;</p></li></ol><div class="warning custom-block"><p class="custom-block-title">安卓用户注意</p><p>安卓设备使用手机内录，需要开启 录屏权限 + 通知权限</p></div><ol start="3"><li><p>然后，去其他 APP 打开你想录制的内容（如播客、B站直播等）开始播放</p></li><li><p>回到 Get 笔记 APP 后，录制页面会有实时转录的文字展示出来，即表示已经在进行录制了</p></li><li><p>最终录制结束后，AI 会自动对音频转写并总结整理</p></li></ol><h2 id="录制时长" tabindex="-1">录制时长 <a class="header-anchor" href="#录制时长" aria-label="Permalink to &quot;录制时长&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>单次时长</th><th>次数限制</th></tr></thead><tbody><tr><td>普通用户</td><td>1 小时</td><td>不限</td></tr><tr><td>会员用户</td><td>3 小时</td><td>不限</td></tr></tbody></table><h2 id="特别说明" tabindex="-1">特别说明 <a class="header-anchor" href="#特别说明" aria-label="Permalink to &quot;特别说明&quot;">​</a></h2><ul><li>手机内录仅通过手机内部声音进行转写，不会录制你的手机屏幕和保存任何视频；</li><li>如果遇到中断暂停等情况，可以点击录音按钮继续录制。</li></ul><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+r+'" alt="手机内录入口" style="width:180px;border-radius:8px;"><img src="'+o+'" alt="授权权限" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="开始录制" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="实时转写" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="录制完成" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="笔记结果" style="width:180px;border-radius:8px;"></div>',17)])])}const q=a(c,[["render",h]]);export{P as __pageData,q as default};
